(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8+Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x-y)*0.01-t*0.45)*8+Math.sin((x+y)*0.011+t*0.55)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.85+4)*55, 0.05, 1.8]
  ];
  let aS=0, iS=0, caustic=0;
  for (const [sX,sY,f,sp] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.sin(d*f*1.618-t*sp*0.7+1.0);
    aS+=w1; iS+=w2; caustic+=w1*w2;
  }
  const act=aS/8, inh=iS/8, caust=caustic/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*5-t*0.9))*0.27;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.4;
  const voroX=sx*0.08, voroY=sy*0.08;
  const vx=Math.floor(voroX), vy=Math.floor(voroY);
  let minD=9;
  for(let dx=-1;dx<=1;dx++) for(let dy=-1;dy<=1;dy++){
    const px=vx+dx, py=vy+dy;
    const nx=px+Math.sin(px*1.7+t*0.4)*0.4+Math.cos(py*2.3+t*0.3)*0.3;
    const ny=py+Math.cos(px*2.1+t*0.5)*0.4+Math.sin(py*1.9+t*0.35)*0.3;
    const d=Math.sqrt((voroX-nx)**2+(voroY-ny)**2);
    if(d<minD) minD=d;
  }
  const cellEdge=Math.smoothstep?0:Math.max(0,1-Math.abs(minD-0.5)*8);
  const voro=1-Math.min(1,minD*1.5);
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+ripple*0.5+caust*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.6+cell*0.15+voro*0.1+caust*0.15;
  const v=blend*0.5+0.5;
  const pal=[[6,12,48],[12,48,88],[18,95,118],[30,145,135],[85,175,140],[165,195,105],[210,175,75],[215,125,70],[175,65,75],[95,28,55],[45,15,48],[6,12,48]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.25;
  const edgeBoost=Math.abs(reaction)>0.6?1.12:1.0;
  const caustGlow=caust>0.2?1.0+caust*0.15:1.0;
  const m=lum*edgeBoost*caustGlow;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
